def main():
 ap=argparse.ArgumentParser();ap.add_argument('--contract',type=Path,default=Path('specs/recurrent_parallel_appworld_census_v1.json'));ap.add_argument('--output-dir',type=Path,default=Path('results/recurrent_parallel_appworld_preflight'));ap.add_argument('--skip-verify',action='store_true');a=ap.parse_args();cp=R(a.contract);c=json.loads(cp.read_text());parentp=R(c['parent_contract']);parent=json.loads(parentp.read_text());runtime=R(c['runtime']['root']);python=R(c['runtime']['python']);cli=R(c['runtime']['cli']);data=runtime/'data';out=R(a.output_dir);out.mkdir(parents=True,exist_ok=True)
 if c.get('schema')!=SCHEMA or c.get('status')!='FROZEN_BEFORE_MODEL_OUTCOMES':raise ValueError('AppWorld census contract not frozen')
 version_run=run([str(python),'-c','import appworld,platform; print(appworld.__version__); print(platform.python_version())']);version_lines=version_run.stdout.strip().splitlines();package_version=version_lines[0] if version_lines else '';python_version=version_lines[1] if len(version_lines)>1 else '';data_version=(data/'version.txt').read_text().strip();verify_checks={}
