 lines=['# AppWorld Recurrent Parallel Specialists — A1 Preflight','',f"## Verdict: **`{status}`**",'',f"- Package: `appworld=={package_version}`",f"- Python: {python_version}",f"- Data version: {data_version}",'- Docker used: No','- GPU/model used: No',f"- Official verification: {verify_mode}",f"- Multi-app candidates: {len(rows)} episodes / {sum(candidate_types.values())} independent task types",'- Test task content inspected: No','','## Checks','']+[f"- `{k}`: **{'PASS' if v else 'FAIL'}**" for k,v in checks.items()]+['','## Candidate pool','', '| Split | Episodes | Independent task types |','|---|---:|---:|']+[f"| {split} | {candidate_counts[split]} | {candidate_types[split]} |" for split in c['selection']['splits']]+['','This establishes a working no-Docker online environment and a gold-blinded multi-app development pool. It authorizes only A2 no-LLM controller work; no Qwen or test-set claim is made.']
 (out/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'status':status,'candidates':len(rows),'task_types':sum(candidate_types.values()),'report':str((out/'REPORT.md').relative_to(REPO_ROOT))}))
